    public record LabSampleRequest(
            @NotBlank String requestId,
            @NotNull @Min(1) @Max(2) Integer samplePoint) {
    }

    /** 返调请求：追加组分，生成引用原批次的新调合批次。 */
    public record ReblendRequest(
            @NotBlank String requestId,
            @NotEmpty List<@Valid ComponentQty> additionalComponents) {
    }

    /** 调合单响应：含合成指标快照与卡边提示。 */
    public record OrderResponse(
            long orderId,
            String requestId,
            String status,
            String blendTankCode,
            String productCode,
            BigDecimal targetQtyKg,
            long activeBatchId,
            BlendModel.IndicatorSet indicators,
            List<BlendModel.EdgeHint> edgeHints,
            boolean replayed) {
    }

    /** 化验样本响应：late=TRUE 表示封账后迟到数据，仅记录不改判定。 */
    public record LabSampleResponse(
            long sampleId,
            String requestId,
            long orderId,
            long batchId,
            int samplePoint,
            BlendModel.IndicatorSet indicators,
            boolean passed,
            boolean late,
            String orderStatus,
            String batchStatus,
            List<BlendModel.EdgeHint> edgeHints,
            boolean replayed) {
    }

    /** 返调响应：新批次引用原批次，指标为累计调合量的复算结果。 */
    public record ReblendResponse(
            long orderId,
            long newBatchId,
            int batchNo,
            long parentBatchId,
            String orderStatus,
            BlendModel.IndicatorSet indicators,
            List<BlendModel.EdgeHint> edgeHints,
            boolean replayed) {
    }

    /** 封账响应：重复封账返回幂等成功。 */
    public record ReleaseResponse(
            long orderId,
            String status,
            Instant releasedAt,
            boolean replayed) {
    }

    /** 批次链视图。 */
    public record BatchView(
            long batchId,
            int batchNo,
            Long parentBatchId,
            String status,
            BigDecimal totalQtyKg,
            BlendModel.IndicatorSet indicators) {
    }

    /** 化验样本视图。 */
    public record SampleView(
            long sampleId,
            long batchId,
            int samplePoint,
            BlendModel.IndicatorSet indicators,
            boolean passed,
            boolean late) {
    }

    /** 切罐流水视图。 */
    public record MovementView(
            long batchId,
            String tankCode,
            BigDecimal qtyKg) {
    }

    /** 调合单详情：指标、卡边率与批次链均可复算，重复查询结果稳定。 */
    public record OrderDetailResponse(
            long orderId,
            String requestId,
            String status,
            String blendTankCode,
            String productCode,
            BigDecimal targetQtyKg,
            Instant createdAt,
            Instant releasedAt,
            BlendModel.IndicatorSet indicators,
            List<BlendModel.EdgeHint> edgeHints,
            List<BatchView> batches,
            List<SampleView> samples,
            List<MovementView> movements) {
    }
}

package com.example.starter.blend;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码。409 用于幂等冲突 / 并发冲突 / 非法状态流转；
 * 422 用于业务规则校验失败（如组分不足、未知牌号）；404 用于资源不存在。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }
}

